html:
{% set company_name = frappe.db.get_value("Company", doc.company, "company_name") %}
{% set company_logo = frappe.db.get_value("Company", doc.company, "company_logo") %}
{% set company_phone_no = frappe.db.get_value("Company", doc.company, "phone_no") %}
{% set company_email = frappe.db.get_value("Company", doc.company, "email") %}
{% set company_website = frappe.db.get_value("Company", doc.company, "website") %}
{% set company_pin = frappe.db.get_value("Company", doc.company, "tax_id") %}

{% set address_name = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") %}
{% set company_address = frappe.db.get_value("Address", address_name, ["address_line1", "address_line2", "city", "pincode", "country"], as_dict=True) %}

{% set doc_label = {
    "Sales Order": "Order #",
    "Sales Invoice": "Invoice #",
    "Purchase Order": "PO #",
    "Purchase Invoice": "Bill #",
    "Purchase Receipt": "PR #",
    "Delivery Note": "DN #",
    "Quotation": "Quote #",
    "Journal Entry": "Journal #",
    "Payment Entry": "Payment #"
}.get(doc.doctype, doc.doctype + " #") %}

<style>
    @media print {
        .doctype-heading {
            background-color: #0056b3 !important;
            color: #fff !important;
            -webkit-print-color-adjust: exact;
        }
    }
</style>

<div id="header-html" style="margin: 20px auto; width: 98%; padding: 15px; border: 2px solid #000; border-radius: 8px; background-color: #f9f9f9; box-shadow: 0px 4px 8px rgba(0, 0, 0, 0.1);">
    <div style="display: flex; align-items: center;">
        <!-- Logo and Company Details -->
        <div style="flex: 1; display: flex; align-items: flex-start;">
            {% if company_logo %}
                <img src="{{ company_logo }}" alt="Company Logo" style="max-width: 100px; max-height: 120px; height: auto; margin-right: 20px; border: 1px solid #ccc; padding: 5px; border-radius: 5px;">
            {% else %}
                <img src="/files/default_logo.jpeg" alt="Default Company Logo" style="max-width: 100px; max-height: 120px; height: auto; margin-right: 20px; border: 1px solid #ccc; padding: 5px; border-radius: 5px;">
            {% endif %}
            <div style="font-size: 12px; line-height: 1.6; color: #333;">
                <strong style="font-size: 14px; color: #000;">{{ company_name }}</strong><br>
                {% if company_address %}
                    {{ company_address.address_line1 }}{% if company_address.pincode %}, {{ company_address.pincode }}{% endif %}<br>
                    {% if company_address.address_line2 %}
                        {{ company_address.address_line2 }},<br>
                    {% endif %}
                    {{ company_address.city }},
                    {{ company_address.country }}.<br>
                {% endif %}
                {% if company_phone_no %}
                    Phone: {{ company_phone_no }}<br>
                {% endif %}
                {% if company_email %}
                    Email: {{ company_email }}<br>
                {% endif %}
                {% if company_website %}
                    Website: <a href="http://{{ company_website }}" style="color: #0056b3; text-decoration: none;">{{ company_website }}</a>
                {% endif %}
            </div>
        </div>

        <!-- Table with Doctype Heading, Date, Number -->
        <div style="flex: 0.8; text-align: left; margin-left: 20px;">
            <table class="table table-sm" style="width: 100%; font-size: 11px; text-align: left; border-collapse: collapse;">
                <tbody>
                    <tr>
                        <td colspan="2" class="doctype-heading" style="text-align: center; font-size: 14px; font-weight: bold; padding: 8px; border-radius: 4px; background-color: #0056b3; color: #fff;">{{ doc.doctype | upper }}</td>
                    </tr>
                    <tr>
                        <td style="padding: 5px; border-bottom: 1px solid #ddd;">Date:</td>
                        <td style="padding: 5px; border-bottom: 1px solid #ddd;">{{ frappe.utils.formatdate(doc.get("transaction_date") or doc.get("posting_date") or "", "dd-MM-yyyy") }}</td>
                    </tr>
                    <tr>
                        <td style="padding: 5px; border-bottom: 1px solid #ddd;">{{ doc_label }}:</td>
                        <td style="padding: 5px; border-bottom: 1px solid #ddd;">{{ doc.name }}</td>
                    </tr>
                </tbody>
            </table>
        </div>
    </div>
</div>

<!-- Supplier Address & QR Code -->
<table class="" style="width:98%; font-size:11px !important; border-bottom:0px solid black !important; margin-bottom: 0px;">
    <tr>
        <td style="width:40%">
            <div style="font-size:13px; margin-bottom: 10px;"><b>From (Supplier),</b></div>
            <div><b>{{ doc.supplier }}</b></div>
            <div><b>{{ doc.supplier_name }}</b></div>
            <div>
                {% set supplier_address_display = frappe.db.get_value('Address', doc.supplier_address, 'display') if doc.supplier_address else '' %}
                {{ supplier_address_display }}
            </div>
        </td>
        <td style="width:20%; text-align: center;">
            {% set base_url = frappe.utils.get_url() %}
            {% set doc_url = base_url + '/app/purchase-receipt/' + doc.name %}

            <img src="https://api.qrserver.com/v1/create-qr-code/?data={{ doc_url | urlencode }}&size=150x150&margin=1&format=png&qzone=1"
                alt="QR Code"
                style="width: 80px; height: 80px; display: block; margin: 0 auto; border: 1px solid #ccc;">

            <!-- Status based on docstatus -->
            {% if doc.docstatus == 1 %}
            <div style="
                background-color: #4CAF50;
                color: white;
                font-size: 10px;
                font-weight: bold;
                padding: 2px 6px;
                border-radius: 4px;
                margin-top: 4px;
                display: inline-block;
            ">
                ✓ Completed
            </div>
            {% elif doc.docstatus == 0 %}
            <div style="
                background-color: #FFC107;
                color: black;
                font-size: 10px;
                font-weight: bold;
                padding: 2px 6px;
                border-radius: 4px;
                margin-top: 4px;
                display: inline-block;
            ">
                Pending
            </div>
            {% else %}
            <div style="
                background-color: #6c757d;
                color: white;
                font-size: 10px;
                font-weight: bold;
                padding: 2px 6px;
                border-radius: 4px;
                margin-top: 4px;
                display: inline-block;
            ">
                Cancelled
            </div>
            {% endif %}
        </td>
        <td style="width:35%">
            <table class="table table-sm" style="width:100%; margin-top:-1px !important;" cellspacing="0" cellpadding="0">
                <tr>
                    <td style='font-size:11px'>PO Date:</td>
                    <td style='font-size:11px'>
                        {% if doc.purchase_order %}
                            {{ frappe.utils.formatdate(frappe.db.get_value('Purchase Order', doc.purchase_order, 'transaction_date'), "dd-MM-yyyy") }}
                        {% endif %}
                    </td>
                </tr>
                <tr>
                    <td style='font-size:11px'>PO #:</td>
                    <td style='font-size:11px'>{{ doc.purchase_order or '' }}</td>
                </tr>
                <tr>
                    <td style='font-size:11px'>Project:</td>
                    <td style='font-size:11px'>{{ doc.project or '' }}</td>
                </tr>
                <tr>
                    <td style='font-size:11px'>Supplier Ref:</td>
                    <td style='font-size:11px'>{{ doc.supplier_delivery_note or '' }}</td>
                </tr>
                {% if doc.is_return == 1 %}
                <tr>
                    <td style='font-size:11px'>Return Against:</td>
                    <td style='font-size:11px'>{{ doc.return_against or '' }}</td>
                </tr>
                {% endif %}
            </table>
        </td>
    </tr>
</table>

<!-- Warehouse, Transporter, Project, etc. -->
<table style="width: 98%; border: 0px solid white !important; margin-top: 0px;">
    {% set unique_warehouses = [] %}
    {% for row in doc.items %}
        {% if row.warehouse not in unique_warehouses %}
            {% set _ = unique_warehouses.append(row.warehouse) %}
        {% endif %}
    {% endfor %}
    {% if unique_warehouses|length == 1 %}
        {% set unique_warehouses = unique_warehouses[0] %}
    {% else %}
        {% set unique_warehouses = unique_warehouses|join(', ') %}
    {% endif %}
    <tr style="border: 0px solid white;">
        <td style='font-size:9px; margin-top: 0px;'>Warehouse: {{ unique_warehouses }}</td>
        <td style='font-size:9px'>Transporter: {{ doc.transporter or '' }}</td>
        <td style='font-size:9px; text-indent: 10px;'>Project No: {{ doc.project or '' }}</td>
        <td class="text-size-10" style='font-size:10px'>PO # {{ doc.purchase_order or '' }}</td>
    </tr>
</table>

<!-- Additional Notes -->
<table style="width:98%; font-size:11px; margin-top:2px">
    <tr width=100% height=40px style="border: 1px solid black;">
        <td width=50%><b>Additional Notes:</b><br>{{ doc.remarks or doc.posa_notes or '' }}</td>
    </tr>
</table>

<!-- Further Action / Instructions -->
<table style="width:98%; font-size:11px; margin-top:2px">
    <tr width=100% height=auto style="border: 1px solid black;">
        <td width=50%><b>Further Action:</b><br>{{ doc.instructions or '' }}</td>
    </tr>
</table>

<!-- Return Reason (if return) -->
{% if doc.is_return == 1 %}
<table style="width:98%; font-size:11px; margin-top:2px">
    <tr width=100% height=auto style="border: 1px solid black;">
        <td width=50%><b>Return Reason:</b><br>{{ doc.return_reason }}</td>
    </tr>
</table>
{% endif %}

{% if doc.docstatus==0 %}
<div class='watermark'></div>
{% endif %}

<!-- Items Table -->
<table style="width:98%; font-size:11px; margin-top:5px" border="1">
    <thead>
        <tr>
            <th style="width:2%">#</th>
            <th style="width:13%">Item Code</th>
            <th style="width:30%">Item Name</th>
            <th style="width:10%" class="text-center">PCS</th>
            <th style="width:10%" class="text-center">QTY</th>
            <th style="width:15%" class="text-center">UOM</th>
        </tr>
    </thead>
    {% set tot_qty = {"tot_qty": 0} %}
    {% set tot_pcs = {"tot_pcs": 0} %}
    {% set tot_weight = {"tot_weight": 0} %}
    {% set tot_unit_weight = {"tot_unit_weight": 0} %}
    {% set uoms_object = {} %}

    {% for row in doc.items %}
        {% if row.uom not in uoms_object.keys() %}
            {% set _ = uoms_object.update({row.uom: 0.0}) %}
        {% endif %}
        {% set _ = uoms_object.update({row.uom: uoms_object[row.uom] + row.qty}) %}
        {% set _ = tot_qty.update({"tot_qty": tot_qty["tot_qty"] + row.qty}) %}
        {% set _ = tot_weight.update({"tot_weight": tot_weight["tot_weight"] + (row.total_weight or 0)}) %}
        {# PCS – adjust if you have a custom field 'pcs' on the item row #}
        {% set pcs = row.pcs or 0 %}
        {% set _ = tot_pcs.update({"tot_pcs": tot_pcs["tot_pcs"] + (pcs if row.uom != 'Nos' else 0)}) %}
        <tr>
            <td>{{ row.idx }}</td>
            <td>{{ row.item_code }}</td>
            <td>{{ row.item_name }}</td>
            <td class="text-center">{{ pcs if row.uom != 'Nos' }}</td>
            <td class="text-center">{{ row.qty }}</td>
            <td class="text-center">{{ row.uom }}</td>
        </tr>
    {% endfor %}
    <tr>
        <td colspan="3" class="text-right"><b>Totals:</b></td>
        <td class="text-center"><b>{{ tot_pcs["tot_pcs"] }}</b></td>
        <td class="text-center"><b>{{ tot_qty["tot_qty"]|round(2) }}</b></td>
        <td class="text-center"><b></b></td>
    </tr>
</table>

<!-- Totals by UOM & Weight -->
<table style="width:98%; font-size:11px; margin-top:2px">
    <tr rowspan="1" style="border-top: 1px solid black; border-bottom: 1px solid black">
        <td colspan="1" style="border: 1px solid black"><b>Total Weight: {{ tot_weight["tot_weight"]|round(3) }}</b></td>
        {% for key, val in uoms_object.items() %}
            <td colspan="1" style="border: 1px solid black"><b>Total {{ key }}: {{ val | round(2) }}</b></td>
        {% endfor %}
    </tr>
</table>

{% if doc.docstatus==0 %}
<div class='watermark'></div>
{% endif %}

<!-- Footer: Created By, Authorized By, Vehicle, etc. -->
<table width=98% style="width:98%; font-size:11px; margin-top:8px">
    <tr width=100% style="border:1px solid black">
        <td width=50% style="border:1px solid black; font-size:11px; font-weight:bold;"><b>Created By: {{ doc.owner }}</b></td>
        <td width=50% style="border:1px solid black; font-size:11px; font-weight:bold;"><b></b></td>
    </tr>
    <tr width=100%>
        <td width=50% style="border:1px solid black; font-size:11px; font-weight:bold;"><b>Created On: {{ doc.get_formatted('creation') }}</b></td>
        <td width=50% style="border:1px solid black; font-size:11px; font-weight:bold;"><b>Authorized By: {% if doc.docstatus==1 %}{{ doc.owner }}{% endif %}</b></td>
    </tr>
    <tr width=100%>
        <td colspan="2" style="border:1px solid black; padding:0px !important; margin:0px !important;">
            <div style="padding:0px !important; margin:0px !important;">
                <table width=100% style="width:100%; padding:0px !important; margin:0px !important; font-size:11px; margin-top:8px">
                    <tr width=100%>
                        <td width=100% style="font-size:11px; font-weight:bold; padding:0px !important; margin:0px !important;"><b>Vehicle Reg:</b></td>
                    </tr>
                    <tr width=100%>
                        <td width=100% style="font-size:11px; font-weight:bold; padding:0px !important; margin:0px !important;"><b>Collector Tel No:</b></td>
                    </tr>
                    <tr width=100%>
                        <td width=100% style="font-size:11px; font-weight:bold; padding:0px !important; margin:0px !important;"><b>Date:</b></td>
                    </tr>
                    <tr width=100%>
                        <td width=100% style="font-size:11px; padding:0px !important; margin:0px !important;"><b>[Goods Checked & Received in good order and condition]</b></td>
                    </tr>
                </table>
            </div>
        </td>
    </tr>
</table>

<!-- Terms and Conditions -->
