<!-- Duplicate / Times Printed Handling -->
{% set times_printed = doc.times_printed or 0 %}
{% if times_printed >= 1 %}
    {% set duplicate = 'DUPLICATE' %}
{% endif %}

{% set footer = frappe.db.get_value("Letter Head", doc.letter_head, "footer") %}
{% if footer %}
    {% set footer_updated = frappe.render_template(footer, {"created_by": doc.owner, "creation": frappe.utils.now(), "user_phone": frappe.db.get_value("User", frappe.session.user, "mobile_no"), "user": frappe.session.user, 'times_printed': times_printed, 'duplicate': duplicate or ''}) %}
    {{ footer_updated }}
{% endif %}

<div id="footer-html" class="visible-pdf visible-print text-center" style="font-size:10px">
    <div class="letter-head-footer text-size-10 text-center" style="font-size: 10px;">
        {{ footer or '' }}
    </div>
</div>

<div style="position: fixed; bottom: 0; left: 0; width: 100%; text-align: center; padding: 10px 0; font-size: 10px; color: #666; background-color: #ffffff; border-top: 1px solid #e9ecef; z-index: 1000;">
    <p style="margin: 0; line-height: 1.5;"></p>
    <p style="margin: 5px 0 0; line-height: 1.5; font-size: 9px; color: #999;"></p>
</div>
